1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  getMeusCombos, getComboDetalhe, criarCombo, editarCombo, deletarCombo,
5	  getMeusProdutos,
6	} from '../../services/restauranteService';
7	import Icon from '../../components/AppIcon';
8	import RestauranteHeader from '../../components/restaurante/RestauranteHeader';
9	
10	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
11	
12	const EMPTY_FORM = { name: '', description: '', image_url: '', destaque: false, items: [] };
13	
14	const RestauranteCombos = () => {
15	  const navigate = useNavigate();
16	  const [combos, setCombos] = useState([]);
17	  const [produtos, setProdutos] = useState([]);
18	  const [loading, setLoading] = useState(true);
19	  const [erro, setErro] = useState(null);
20	  const [showModal, setShowModal] = useState(false);
21	  const [editando, setEditando] = useState(null);
22	  const [form, setForm] = useState(EMPTY_FORM);
23	  const [salvando, setSalvando] = useState(false);
24	  const [deletando, setDeletando] = useState(null);
25	  const [alternando, setAlternando] = useState(null);
26	
27	  const carregar = () => {
28	    setLoading(true);
29	    Promise.all([getMeusCombos(), getMeusProdutos()])
30	      .then(([c, p]) => {
31	        setCombos(c.combos ?? []);
32	        setProdutos(p.produtos ?? []);
33	      })
34	      .catch((e) => setErro(e.message))
35	      .finally(() => setLoading(false));
36	  };
37	
38	  useEffect(() => { carregar(); }, []);
39	
40	  const abrirNovo = () => {
41	    setEditando(null);
42	    setForm(EMPTY_FORM);
43	    setShowModal(true);
44	  };
45	
46	  const abrirEditar = async (combo) => {
47	    try {
48	      const detalhe = await getComboDetalhe(combo.id);
49	      setEditando(detalhe);
50	      setForm({
51	        name: detalhe.name ?? '',
52	        description: detalhe.description ?? '',
53	        image_url: detalhe.image_url ?? '',
54	        destaque: detalhe.destaque ?? false,
55	        items: (detalhe.items ?? []).map((i) => ({
56	          product_id: i.product_id,
57	          quantity: i.quantity,
58	          preco_no_combo: i.preco_no_combo ?? i.products?.price ?? 0,
59	        })),
60	      });
61	      setShowModal(true);
62	    } catch (e) {
63	      alert(e.message);
64	    }
65	  };
66	
67	  const fecharModal = () => {
68	    setShowModal(false);
69	    setEditando(null);
70	    setForm(EMPTY_FORM);
71	  };
72	
73	  const addItem = (product_id) => {
74	    const id = parseInt(product_id);
75	    if (!id) return;
76	    const prod = prodMap[id];
77	    setForm((f) => {
78	      if (f.items.some((i) => i.product_id === id)) return f;
79	      // Preço no combo começa igual ao preço real — o dono abaixa se quiser dar desconto.
80	      return { ...f, items: [...f.items, { product_id: id, quantity: 1, preco_no_combo: prod?.price ?? 0 }] };
81	    });
82	  };
83	
84	  const removeItem = (product_id) => {
85	    setForm((f) => ({ ...f, items: f.items.filter((i) => i.product_id !== product_id) }));
86	  };
87	
88	  const setQty = (product_id, qty) => {
89	    setForm((f) => ({
90	      ...f,
91	      items: f.items.map((i) => i.product_id === product_id ? { ...i, quantity: Math.max(1, parseInt(qty) || 1) } : i),
92	    }));
93	  };
94	
95	  const setPrecoNoCombo = (product_id, valor) => {
96	    setForm((f) => ({
97	      ...f,
98	      items: f.items.map((i) => i.product_id === product_id ? { ...i, preco_no_combo: Math.max(0, parseFloat(valor) || 0) } : i),
99	    }));
100	  };
101	
102	  const handleSalvar = async (e) => {
103	    e.preventDefault();
104	    if (!form.name) { alert('Nome é obrigatório'); return; }
105	    if (form.items.length === 0) { alert('Adicione pelo menos 1 produto ao combo'); return; }
106	    setSalvando(true);
107	    const payload = {
108	      name: form.name,
109	      description: form.description || null,
110	      image_url: form.image_url || null,
111	      destaque: form.destaque,
112	      items: form.items,
113	    };
114	    try {
115	      if (editando) {
116	        const atualizado = await editarCombo(editando.id, payload);
