1	import { BadRequestException, ConflictException, ForbiddenException, UnauthorizedException, Injectable } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import * as bcrypt from 'bcryptjs';
4	import * as crypto from 'crypto';
5	import * as jwt from 'jsonwebtoken';
6	import { SupabaseService } from '../supabase/supabase.service';
7	
8	const SESSION_TTL_MS = 12 * 60 * 60 * 1000; // igual ao expiresIn do JWT
9	
10	@Injectable()
11	export class GarcomAuthService {
12	  constructor(
13	    private supabase: SupabaseService,
14	    private config: ConfigService,
15	  ) {}
16	
17	  private gerarToken(garcomId: number, sessionId: string): string {
18	    const secret = this.config.getOrThrow('GARCOM_JWT_SECRET');
19	    return jwt.sign({ garcomId, sessionId }, secret, { expiresIn: '12h' });
20	  }
21	
22	  // Só abre sessão nova se não houver outra ativa (ou se a anterior já expirou) —
23	  // update condicional atômico evita corrida entre dois logins simultâneos.
24	  private async abrirSessao(garcomId: number): Promise<string> {
25	    const sessionId = crypto.randomUUID();
26	    const nowIso = new Date().toISOString();
27	    const expiresAt = new Date(Date.now() + SESSION_TTL_MS).toISOString();
28	
29	    const { data } = await this.supabase.client
30	      .from('garcons')
31	      .update({ active_session_id: sessionId, session_expires_at: expiresAt })
32	      .eq('id', garcomId)
33	      .or(`active_session_id.is.null,session_expires_at.lt.${nowIso}`)
34	      .select('id')
35	      .maybeSingle();
36	
37	    if (!data) {
38	      throw new ConflictException('Este garçom já está logado em outro dispositivo. Peça pro estabelecimento liberar o acesso.');
39	    }
40	    return sessionId;
41	  }
42	
43	  async login(loginKey: string, password: string) {
44	    if (!loginKey || !password) throw new BadRequestException('Informe usuário e senha');
45	
46	    const { data: garcom } = await this.supabase.client
47	      .from('garcons')
48	      .select('id, password_hash, ativo, restaurants(aparencia)')
49	      .eq('login_key', loginKey)
50	      .maybeSingle();
51	
52	    if (!garcom?.password_hash) throw new UnauthorizedException('Credenciais inválidas');
53	    if (!garcom.ativo) throw new UnauthorizedException('Acesso desativado');
54	
55	    const ok = await bcrypt.compare(password, garcom.password_hash);
56	    if (!ok) throw new UnauthorizedException('Credenciais inválidas');
57	
58	    const restauranteAberto = (garcom as any).restaurants?.aparencia?.aberto === true;
