1	import { Injectable } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { normalizarDominio } from './dominio.util';
5	
6	// Allowlist de CORS pra um SaaS multi-tenant com domínio próprio por loja
7	// (custom_domain): a base fixa (app principal, dev) vem de env; os domínios
8	// White Label vêm do banco e mudam com frequência — cache curto em memória
9	// evita bater no Supabase a cada preflight sem deixar a lista ficar velha.
10	@Injectable()
11	export class CorsOriginsService {
12	  private cache: { origens: Set<string>; expiraEm: number } | null = null;
13	  private readonly TTL_MS = 60_000;
14	
15	  constructor(
16	    private supabase: SupabaseService,
17	    private config: ConfigService,
18	  ) {}
19	
20	  private origensBase(): string[] {
21	    return (this.config.get<string>('APP_ALLOWED_ORIGINS') ?? '')
22	      .split(',')
23	      .map((s) => normalizarDominio(s.trim()))
24	      .filter(Boolean);
25	  }
26	
27	  private async origensDinamicas(): Promise<string[]> {
28	    const { data } = await this.supabase.client
29	      .from('restaurants')
30	      .select('custom_domain')
31	      .not('custom_domain', 'is', null)
32	      // aprovado = sem pendência nem recusa (ver empresas.service.ts atenderSolicitacaoDominio)
33	      .is('custom_domain_status', null);
34	    return (data ?? [])
35	      .map((r: { custom_domain: string }) => normalizarDominio(r.custom_domain))
36	      .filter(Boolean);
37	  }
38	
39	  async estaPermitida(origin: string): Promise<boolean> {
40	    const dominio = normalizarDominio(origin);
41	    if (this.origensBase().includes(dominio)) return true;
42	
43	    const agora = Date.now();
44	    if (!this.cache || agora > this.cache.expiraEm) {
45	      const dinamicas = await this.origensDinamicas();
46	      this.cache = { origens: new Set(dinamicas), expiraEm: agora + this.TTL_MS };
47	    }
48	    return this.cache.origens.has(dominio);
49	  }
50	}
